"""RFC-822 email -> Email dataclass.  Deterministic, stdlib only.

Everything here is *code's* job: decoding MIME, choosing the body rendering, splitting the
current message from quoted history, and collecting attachments (including attachments of
message/rfc822 parts, e.g. a bounce carrying the original order).
"""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass, field
from email import policy
from email.message import EmailMessage
from email.parser import BytesParser
from email.utils import getaddresses, parsedate_to_datetime
from datetime import datetime, timezone
from html.parser import HTMLParser
from pathlib import Path

OUR_DOMAIN = "ridgeline-supply.example"


@dataclass
class Attachment:
    filename: str
    mime: str
    data: bytes
    inline: bool = False
    content_id: str | None = None
    nested_in: str | None = None  # filename of the .eml this came out of, if any

    @property
    def sha256(self) -> str:
        return hashlib.sha256(self.data).hexdigest()


@dataclass
class Email:
    id: str
    raw_sha256: str
    from_name: str
    from_addr: str
    to: str
    cc: str
    date: datetime | None
    subject: str
    message_id: str | None
    in_reply_to: str | None
    references: list[str]
    headers_text: str  # the few headers worth showing a model
    body: str  # full rendered body (current + quoted)
    current: str  # the part the sender wrote now
    history: str  # quoted reply history / forwarded content
    history_kind: str | None  # "reply_quote" | "forward" | None
    attachments: list[Attachment] = field(default_factory=list)
    auto_headers: list[str] = field(default_factory=list)  # Auto-Submitted etc.
    problems: list[str] = field(default_factory=list)

    @property
    def from_us(self) -> bool:
        return self.from_addr.lower().endswith("@" + OUR_DOMAIN)

    @property
    def sender_domain(self) -> str:
        return self.from_addr.rsplit("@", 1)[-1].lower() if "@" in self.from_addr else ""


# --------------------------------------------------------------------------- HTML -> text


class _HtmlText(HTMLParser):
    """HTML to text that keeps what matters for RFQs: table rows (cells joined by ' | '),
    line breaks, struck-through text (marked), and inline image references."""

    BLOCK = {"p", "div", "br", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6", "table", "blockquote"}
    STRIKE_TAGS = {"s", "strike", "del"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out: list[str] = []
        self.strike_depth = 0
        self.tag_strike: list[bool] = []
        self.skip = 0
        self.cell_open = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("style", "script", "head", "title"):
            self.skip += 1
            return
        style = (a.get("style") or "").replace(" ", "").lower()
        struck = tag in self.STRIKE_TAGS or "line-through" in style
        if tag not in ("br", "img", "hr", "meta", "input"):
            self.tag_strike.append(struck)
        if struck:
            self.strike_depth += 1
            self.out.append("[STRUCK: ")
        if tag in ("td", "th"):
            if self.cell_open:
                self.out.append(" | ")
            self.cell_open = True
        elif tag == "tr":
            self.out.append("\n")
            self.cell_open = False
        elif tag in self.BLOCK:
            self.out.append("\n")
        if tag == "img":
            src = a.get("src") or ""
            alt = a.get("alt") or ""
            self.out.append(f"[image {src}{' alt=' + repr(alt) if alt else ''}]")

    def handle_endtag(self, tag):
        if tag in ("style", "script", "head", "title"):
            self.skip = max(0, self.skip - 1)
            return
        if tag in ("br", "img", "hr", "meta", "input"):
            return
        if self.tag_strike:
            struck = self.tag_strike.pop()
            if struck:
                self.strike_depth -= 1
                self.out.append("]")
        if tag in ("p", "div", "tr", "table", "li", "blockquote") or tag.startswith("h"):
            self.out.append("\n")
            if tag == "tr":
                self.cell_open = False

    def handle_data(self, data):
        if self.skip:
            return
        self.out.append(re.sub(r"\s+", " ", data))

    def text(self) -> str:
        s = "".join(self.out)
        s = re.sub(r"[ \t]+\n", "\n", s)
        s = re.sub(r"\n[ \t]+", "\n", s)
        s = re.sub(r"\n{3,}", "\n\n", s)
        return s.strip()


def html_to_text(html: str) -> str:
    p = _HtmlText()
    try:
        p.feed(html)
        p.close()
    except Exception:  # malformed HTML: fall back to tag stripping
        return re.sub(r"<[^>]+>", " ", html)
    return p.text()


def _html_is_richer(html: str) -> bool:
    """Use the HTML rendering instead of text/plain when it carries structure plain text loses."""
    h = html.lower()
    return any(k in h for k in ("<table", "<s>", "<strike", "<del", "line-through"))


# --------------------------------------------------------------------------- quoting


_REPLY_HDR = re.compile(r"^\s*On .{5,200}wrote:\s*$", re.M)
_FWD_MARK = re.compile(
    r"^\s*(-{2,}\s*(Original Message|Forwarded message)\s*-{2,}|Begin forwarded message:)\s*$",
    re.I | re.M,
)
_OUTLOOK_HDR = re.compile(r"^\s*From:\s.+\n(\s*(Sent|Date):\s.+\n)", re.M)


def split_history(body: str, subject: str) -> tuple[str, str, str | None]:
    """Split a body into (current, history, kind).  Kind is 'forward' when the earlier
    content is a forwarded message (which counts, per the README, when one of our reps
    forwards), 'reply_quote' for ordinary reply history (which does not count)."""
    cut = None
    kind = None
    m = _FWD_MARK.search(body)
    if m:
        cut, kind = m.start(), "forward"
    for rx in (_REPLY_HDR, _OUTLOOK_HDR):
        m2 = rx.search(body)
        if m2 and (cut is None or m2.start() < cut):
            cut = m2.start()
            kind = "forward" if re.match(r"^\s*fw", subject or "", re.I) and rx is _OUTLOOK_HDR else "reply_quote"
    if cut is None:
        # a run of '>' lines with no header
        m3 = re.search(r"^>.*$", body, re.M)
        if m3:
            cut, kind = m3.start(), "reply_quote"
    if cut is None:
        return body.strip(), "", None
    return body[:cut].strip(), body[cut:].strip(), kind


# --------------------------------------------------------------------------- parsing


def _safe_name(name: str) -> str:
    return re.sub(r"[\\/:*?\"<>|\r\n]+", "_", name).strip() or "unnamed"


def _part_text(part) -> str:
    try:
        return part.get_content()
    except Exception:
        return (part.get_payload(decode=True) or b"").decode("utf-8", "replace")


def _addr(value) -> tuple[str, str]:
    try:
        pairs = getaddresses([str(value or "")])
        if pairs:
            return pairs[0][0] or "", pairs[0][1] or ""
    except Exception:
        pass
    return "", str(value or "")


def _date(value) -> datetime | None:
    try:
        d = parsedate_to_datetime(str(value))
        if d.tzinfo is None:
            d = d.replace(tzinfo=timezone.utc)
        return d
    except Exception:
        return None


def parse_message(msg: EmailMessage, eid: str, raw: bytes, nested_in: str | None = None) -> Email:
    problems: list[str] = []
    text_plain: str | None = None
    text_html: str | None = None
    atts: list[Attachment] = []

    stack = [msg]
    while stack:
        part = stack.pop(0)
        try:
            ct = part.get_content_type()
            if ct == "message/rfc822":
                try:
                    data = part.get_payload(0).as_bytes() if part.is_multipart() else (part.get_payload(decode=True) or b"")
                except Exception:
                    data = bytes(str(part.get_payload()), "utf-8", "replace")
                name = part.get_filename() or f"attached-{len(atts) + 1}.eml"
                atts.append(Attachment(_safe_name(name), "message/rfc822", data, nested_in=nested_in))
                continue
            if part.is_multipart():
                stack[0:0] = list(part.iter_parts())
                continue
            disp = part.get_content_disposition()
            fname = part.get_filename()
            if disp in ("attachment", "inline") and (fname or ct.split("/")[0] != "text"):
                atts.append(
                    Attachment(
                        _safe_name(fname or f"unnamed-{len(atts) + 1}"),
                        ct,
                        part.get_payload(decode=True) or b"",
                        inline=disp == "inline",
                        content_id=(part.get("Content-ID") or "").strip("<> ") or None,
                        nested_in=nested_in,
                    )
                )
            elif ct == "text/plain" and text_plain is None:
                text_plain = _part_text(part)
            elif ct == "text/html" and text_html is None:
                text_html = _part_text(part)
            elif ct.split("/")[0] != "text" or fname:
                atts.append(Attachment(_safe_name(fname or f"unnamed-{len(atts) + 1}"), ct,
                                       part.get_payload(decode=True) or b"", nested_in=nested_in))
        except Exception as e:  # one bad part never sinks the email
            problems.append(f"could not decode a MIME part: {e}")

    if text_html and (text_plain is None or _html_is_richer(text_html)):
        body = html_to_text(text_html)
    else:
        body = text_plain or ""
    body = body.replace("\r\n", "\n")

    from_name, from_addr = _addr(msg.get("from"))
    subject = str(msg.get("subject") or "")
    current, history, kind = split_history(body, subject)
    refs = re.findall(r"<[^>]+>", str(msg.get("references") or ""))
    irt = (re.findall(r"<[^>]+>", str(msg.get("in-reply-to") or "")) or [None])[0]
    auto = [f"{h}: {msg.get(h)}" for h in ("auto-submitted", "x-autoreply", "x-autorespond", "precedence")
            if msg.get(h) and str(msg.get(h)).lower() not in ("no",)]
    date = _date(msg.get("date"))
    hdr = "\n".join(
        f"{k}: {v}" for k, v in (
            ("From", msg.get("from")), ("To", msg.get("to")), ("Cc", msg.get("cc")),
            ("Date", msg.get("date")), ("Subject", subject),
        ) if v
    )
    return Email(
        id=eid,
        raw_sha256=hashlib.sha256(raw).hexdigest(),
        from_name=from_name,
        from_addr=from_addr,
        to=str(msg.get("to") or ""),
        cc=str(msg.get("cc") or ""),
        date=date,
        subject=subject,
        message_id=(str(msg.get("message-id") or "").strip() or None),
        in_reply_to=irt,
        references=refs,
        headers_text=hdr,
        body=body,
        current=current,
        history=history,
        history_kind=kind,
        attachments=atts,
        auto_headers=auto,
        problems=problems,
    )


def load_email(path: Path) -> Email:
    raw = path.read_bytes()
    msg = BytesParser(policy=policy.default).parsebytes(raw)
    return parse_message(msg, path.stem, raw)


def load_nested(data: bytes, eid: str, filename: str) -> Email:
    msg = BytesParser(policy=policy.default).parsebytes(data)
    return parse_message(msg, eid, data, nested_in=filename)

