        return self.from_addr.rsplit("@", 1)[-1].lower() if "@" in self.from_addr else ""


# --------------------------------------------------------------------------- HTML -> text


class _HtmlText(HTMLParser):
    """HTML to text that keeps what matters for RFQs: table rows (cells joined by ' | '),
    line breaks, struck-through text (marked), and inline image references."""

    BLOCK = {"p", "div", "br", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6", "table", "blockquote"}
    STRIKE_TAGS = {"s", "strike", "del"}

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out: list[str] = []
        self.strike_depth = 0
        self.tag_strike: list[bool] = []
        self.skip = 0
        self.cell_open = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("style", "script", "head", "title"):
            self.skip += 1
            return
        style = (a.get("style") or "").replace(" ", "").lower()
        struck = tag in self.STRIKE_TAGS or "line-through" in style
