            ct = part.get_content_type()
            if ct == "message/rfc822":
                try:
                    data = part.get_payload(0).as_bytes() if part.is_multipart() else (part.get_payload(decode=True) or b"")
                except Exception:
                    data = bytes(str(part.get_payload()), "utf-8", "replace")
