                stack[0:0] = list(part.iter_parts())
                continue
            disp = part.get_content_disposition()
            fname = part.get_filename()
            if disp in ("attachment", "inline") and (fname or ct.split("/")[0] != "text"):
                atts.append(
                    Attachment(
                        _safe_name(fname or f"unnamed-{len(atts) + 1}"),
                        ct,
                        part.get_payload(decode=True) or b"",
                        inline=disp == "inline",
                        content_id=(part.get("Content-ID") or "").strip("<> ") or None,
                        nested_in=nested_in,
                    )
                )
            elif ct == "text/plain" and text_plain is None:
                text_plain = _part_text(part)
            elif ct == "text/html" and text_html is None:
                text_html = _part_text(part)
            elif ct.split("/")[0] != "text" or fname:
                atts.append(Attachment(_safe_name(fname or f"unnamed-{len(atts) + 1}"), ct,
                                       part.get_payload(decode=True) or b"", nested_in=nested_in))
        except Exception as e:  # one bad part never sinks the email
            problems.append(f"could not decode a MIME part: {e}")

    if text_html and (text_plain is None or _html_is_richer(text_html)):
        body = html_to_text(text_html)
    else:
        body = text_plain or ""
    body = body.replace("\r\n", "\n")

    from_name, from_addr = _addr(msg.get("from"))
    subject = str(msg.get("subject") or "")
    current, history, kind = split_history(body, subject)
    refs = re.findall(r"<[^>]+>", str(msg.get("references") or ""))
    irt = (re.findall(r"<[^>]+>", str(msg.get("in-reply-to") or "")) or [None])[0]
    auto = [f"{h}: {msg.get(h)}" for h in ("auto-submitted", "x-autoreply", "x-autorespond", "precedence")
            if msg.get(h) and str(msg.get(h)).lower() not in ("no",)]
    date = _date(msg.get("date"))
    hdr = "\n".join(
        f"{k}: {v}" for k, v in (
            ("From", msg.get("from")), ("To", msg.get("to")), ("Cc", msg.get("cc")),
            ("Date", msg.get("date")), ("Subject", subject),
        ) if v
    )
    return Email(
        id=eid,
        raw_sha256=hashlib.sha256(raw).hexdigest(),
        from_name=from_name,
        from_addr=from_addr,
        to=str(msg.get("to") or ""),
        cc=str(msg.get("cc") or ""),
        date=date,
        subject=subject,
        message_id=(str(msg.get("message-id") or "").strip() or None),
        in_reply_to=irt,
        references=refs,
        headers_text=hdr,
        body=body,
        current=current,
        history=history,
        history_kind=kind,
        attachments=atts,
        auto_headers=auto,
        problems=problems,
    )


def load_email(path: Path) -> Email:
    raw = path.read_bytes()
    msg = BytesParser(policy=policy.default).parsebytes(raw)
    return parse_message(msg, path.stem, raw)


def load_nested(data: bytes, eid: str, filename: str) -> Email:
    msg = BytesParser(policy=policy.default).parsebytes(data)
    return parse_message(msg, eid, data, nested_in=filename)

