def image_for_model(data: bytes) -> tuple[bytes, int, int]:
    """Return (png bytes, width, height), downscaled to MAX_IMAGE_SIDE.  Raises if unreadable."""
    import fitz  # PyMuPDF

    pix = fitz.Pixmap(data)
    if pix.alpha:
        pix = fitz.Pixmap(pix, 0)
    if pix.colorspace and pix.colorspace.n not in (1, 3):
        pix = fitz.Pixmap(fitz.csRGB, pix)
    w, h = pix.width, pix.height
    side = max(w, h)
    if side > MAX_IMAGE_SIDE:
        scale = MAX_IMAGE_SIDE / side
        pix = fitz.Pixmap(pix, int(w * scale), int(h * scale), None)
    return pix.tobytes("png"), w, h


