        return Doc(filename, "unreadable", error="PDF is password-protected; it cannot be opened without the password")
    doc = Doc(filename, "text")
    n = pdf.page_count
    if n == 0:
        return Doc(filename, "unreadable", error="PDF has no pages")
    texts, img_pages = [], 0
    for i in range(min(n, MAX_PDF_PAGES)):
        try:
            page = pdf[i]
            lines = _pdf_lines(page)
            txt = "\n".join(lines)
            if len(re.sub(r"\s", "", txt)) < PAGE_TEXT_MIN:
