                    img_pages += 1
                    texts.append(f"--- page {i + 1} of {n}: scanned image, see attached picture ---")
                else:
                    doc.truncated = True
                    texts.append(f"--- page {i + 1} of {n}: scanned image NOT READ (page limit) ---")
            else:
                texts.append(f"--- page {i + 1} of {n} ---\n{txt}")
        except Exception as e:
            texts.append(f"--- page {i + 1} of {n}: could not be read ({e}) ---")
            doc.notes.append(f"page {i + 1} unreadable: {e}")
            doc.truncated = True
