def read_xlsx(filename: str, data: bytes) -> Doc:
    import openpyxl
    from openpyxl.utils import get_column_letter

    try:
        wb = openpyxl.load_workbook(io.BytesIO(data), data_only=True)
    except Exception as e:
        return Doc(filename, "unreadable", error=f"spreadsheet could not be opened (corrupt or unsupported): {e}")
    doc = Doc(filename, "text")
    out = []
    for ws in wb.worksheets:
        if ws.sheet_state != "visible":
            n = sum(1 for r in ws.iter_rows(values_only=True) if any(c is not None for c in r))
            doc.notes.append(f"hidden sheet '{ws.title}' ({n} rows) omitted: hidden sheets hold old revisions/scratch work")
