        merged_cover = set()
        for rng in ws.merged_cells.ranges:
            merged_first[(rng.min_row, rng.min_col)] = rng.coord
            for r in range(rng.min_row, rng.max_row + 1):
                for c in range(rng.min_col, rng.max_col + 1):
                    if (r, c) != (rng.min_row, rng.min_col):
                        merged_cover.add((r, c))
        hidden_cols = {k for k, d in ws.column_dimensions.items() if d.hidden}
        hidden_rows = 0
        lines = [f"=== sheet '{ws.title}' ==="]
        for row in ws.iter_rows():
            if not row:
                continue
            r = row[0].row
            if ws.row_dimensions[r].hidden:
                if any(c.value is not None for c in row):
                    hidden_rows += 1
                continue
            cells = []
            for c in row:
                if (r, c.column) in merged_cover:
                    continue
                if get_column_letter(c.column) in hidden_cols:
                    continue
                s = _cell_str(c.value)
                if not s:
                    cells.append("")
                    continue
                if c.font is not None and c.font.strike:
                    s = f"[STRUCK: {s}]"
                if (r, c.column) in merged_first:
                    s += f"   [merged cell {merged_first[(r, c.column)]}]"
                cells.append(s)
