                cells.pop()
            if any(cells):
                lines.append(f"[row {r}] " + " | ".join(cells))
        if hidden_rows:
            doc.notes.append(f"sheet '{ws.title}': {hidden_rows} hidden row(s) omitted")
        if hidden_cols:
            doc.notes.append(f"sheet '{ws.title}': hidden column(s) {sorted(hidden_cols)} omitted")
