W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


def _w_on(el) -> bool:
    if el is None:
        return False
    v = el.get(W + "val")
    return v is None or v.lower() not in ("0", "false", "none")


def _para_text(p) -> str:
    parts = []
    for r in p.iter(W + "r"):
        rpr = r.find(W + "rPr")
        struck = rpr is not None and (_w_on(rpr.find(W + "strike")) or _w_on(rpr.find(W + "dstrike")))
        t = "".join((x.text or "") if x.tag == W + "t" else ("\t" if x.tag == W + "tab" else "")
                    for x in r if x.tag in (W + "t", W + "tab"))
        if not t:
            continue
        parts.append(f"[STRUCK: {t}]" if struck else t)
    s = "".join(parts)
    return re.sub(r"\]\[STRUCK: ", "", s)


def _strip_deletions(root):
    for parent in root.iter():
        for child in list(parent):
            if child.tag in (W + "del", W + "moveFrom"):
                parent.remove(child)


def read_docx(filename: str, data: bytes) -> Doc:
    try:
        z = zipfile.ZipFile(io.BytesIO(data))
        root = ET.fromstring(z.read("word/document.xml"))
    except Exception as e:
        return Doc(filename, "unreadable", error=f"Word document could not be opened (corrupt): {e}")
    _strip_deletions(root)
    body = root.find(W + "body")
    lines = []

    def walk(el):
        for child in el:
            if child.tag == W + "p":
                t = _para_text(child)
                if t.strip():
                    style = child.find(f"{W}pPr/{W}pStyle")
                    sv = style.get(W + "val") if style is not None else ""
                    lines.append((f"[{sv}] " if sv and sv.lower().startswith(("heading", "title")) else "") + t)
            elif child.tag == W + "tbl":
                lines.append("[table]")
                for tr in child.iter(W + "tr"):
                    cells = []
                    for tc in tr.findall(W + "tc"):
                        cells.append(" ".join(_para_text(p) for p in tc.iter(W + "p")).strip())
                    if any(cells):
                        lines.append(" | ".join(cells))
                lines.append("[/table]")
            elif child.tag == W + "sdt":
                c = child.find(W + "sdtContent")
                if c is not None:
                    walk(c)

    if body is not None:
        walk(body)
    doc = Doc(filename, "text", text="\n".join(lines))
    # images embedded in the document (e.g. a pasted photo of a list)
    for n in z.namelist():
        if n.startswith("word/media/") and len(doc.images) < MAX_IMAGE_PAGES:
            try:
                png, w, h = image_for_model(z.read(n))
                if max(w, h) >= 200:
                    doc.images.append((f"{filename} embedded {n.rsplit('/', 1)[-1]}", png))
            except Exception:
                pass
    if doc.images:
        doc.kind = "mixed"
        doc.notes.append(f"{len(doc.images)} embedded picture(s) included")
    if not doc.text.strip() and not doc.images:
        doc.kind, doc.error = "unreadable", "Word document has no readable content"
    return _cap(doc)


# --------------------------------------------------------------------------- dispatch


def read_attachment(filename: str, mime: str, data: bytes, depth: int = 0) -> Doc:
    """Never raises."""
    try:
        if not data:
            return Doc(filename, "unreadable", error="attachment is empty (0 bytes)")
        kind = sniff(data, filename, mime)
        if kind == "pdf":
            return read_pdf(filename, data)
        if kind == "image":
            return read_image(filename, data)
        if kind == "xlsx":
            return read_xlsx(filename, data)
        if kind == "docx":
            return read_docx(filename, data)
        if kind == "csv":
            txt = _decode_text(data)
            try:
                rows = list(csv.reader(io.StringIO(txt)))
                txt = "\n".join(" | ".join(c.strip() for c in r) for r in rows if any(c.strip() for c in r))
            except Exception:
                pass
            return _cap(Doc(filename, "text", text=txt))
        if kind == "txt":
            return _cap(Doc(filename, "text", text=_decode_text(data)))
        if kind == "html":
            from .mime import html_to_text
            return _cap(Doc(filename, "text", text=html_to_text(_decode_text(data))))
        if kind == "eml":
            return read_eml(filename, data, depth)
        if kind == "ole":
            return Doc(filename, "unreadable", error="legacy Office file (.xls/.doc/.msg) - not supported, open by hand")
        if kind.startswith("mismatch:"):
            return Doc(filename, "unreadable",
                       error=f"file is named .{kind.split(':')[1]} but its contents are not that format (corrupt or mislabelled)")
        if kind == "corrupt_zip":
            return Doc(filename, "unreadable", error="file is a damaged ZIP/Office container")
        return Doc(filename, "unreadable", error=f"unsupported attachment type ({mime})")
    except Exception as e:
        return Doc(filename, "unreadable", error=f"could not read attachment: {type(e).__name__}: {e}")


def read_eml(filename: str, data: bytes, depth: int) -> Doc:
    from .mime import load_nested

    e = load_nested(data, filename, filename)
    txt = f"{e.headers_text}\n\n{e.body}"
    doc = Doc(filename, "text", text=txt, notes=["attached email message"])
    if depth < 2:
        for a in e.attachments:
            doc.nested.append(read_attachment(a.filename, a.mime, a.data, depth + 1))
    return _cap(doc)

