"""Attachment bytes -> Doc (text and/or page images) for the model.

Code decides here, not the model:
  * what a file really is (magic bytes beat the extension),
  * what a human would not see: hidden sheets/rows/columns are dropped (they hold stale
    revisions), struck-through text is marked [STRUCK: ...], tracked deletions are dropped,
  * what cannot be read at all (password, corrupt, unsupported) -> Doc.error, which the
    pipeline turns into needs_review instead of a crash,
  * how much of a huge document is read (page / character caps -> Doc.truncated).
"""

from __future__ import annotations

import csv
import io
import re
import zipfile
