MAX_IMAGE_PAGES = 8  # scanned pages rendered and sent as images, per document
MAX_DOC_CHARS = 60_000  # text sent per document
MAX_IMAGE_SIDE = 2000  # px, longest side sent to the model
MIN_IMAGE_SIDE = 24  # px, smaller images are spacers / tracking pixels
PAGE_TEXT_MIN = 25  # a PDF page with fewer characters is treated as a scan


@dataclass
class Doc:
    filename: str
    kind: str  # text | image | mixed | unreadable | skipped
    text: str = ""
    images: list[tuple[str, bytes]] = field(default_factory=list)  # (label, png/jpeg bytes)
    notes: list[str] = field(default_factory=list)
    error: str | None = None
    truncated: bool = False
    nested: list["Doc"] = field(default_factory=list)  # docs inside an attached .eml


def sniff(data: bytes, filename: str, mime: str) -> str:
    head = data[:8]
    if data[:5] == b"%PDF-" or b"%PDF-" in data[:1024]:
        return "pdf"
    if head.startswith(b"\x89PNG") or head.startswith(b"\xff\xd8") or head.startswith(b"GIF8") \
            or head.startswith(b"BM") or head[:4] in (b"II*\x00", b"MM\x00*") \
            or (data[:4] == b"RIFF" and data[8:12] == b"WEBP"):
        return "image"
    if head.startswith(b"PK"):
        try:
            names = zipfile.ZipFile(io.BytesIO(data)).namelist()
        except Exception:
            return "corrupt_zip"
        if any(n.startswith("xl/") for n in names):
            return "xlsx"
        if any(n.startswith("word/") for n in names):
            return "docx"
        return "zip"
    if head.startswith(b"\xd0\xcf\x11\xe0"):
        return "ole"  # legacy .xls/.doc/.msg
    ext = filename.lower().rsplit(".", 1)[-1] if "." in filename else ""
    if mime == "message/rfc822" or ext == "eml":
        return "eml"
    if ext in ("csv", "tsv") or mime in ("text/csv",):
        return "csv"
    if ext in ("htm", "html") or mime == "text/html":
        return "html"
    if ext in ("txt", "text") or mime.startswith("text/"):
        return "txt"
    if ext in ("pdf", "xlsx", "xlsm", "docx", "png", "jpg", "jpeg", "gif", "tif", "tiff", "bmp", "webp"):
        return "mismatch:" + ext  # name says one thing, bytes say another -> broken
    return "unknown"


def _decode_text(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252", "latin-1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


