        if ws.sheet_state != "visible":
            n = sum(1 for r in ws.iter_rows(values_only=True) if any(c is not None for c in r))
            doc.notes.append(f"hidden sheet '{ws.title}' ({n} rows) omitted: hidden sheets hold old revisions/scratch work")
            continue
        merged_first = {}
        merged_cover = set()
        for rng in ws.merged_cells.ranges:
            merged_first[(rng.min_row, rng.min_col)] = rng.coord
            for r in range(rng.min_row, rng.max_row + 1):
                for c in range(rng.min_col, rng.max_col + 1):
                    if (r, c) != (rng.min_row, rng.min_col):
                        merged_cover.add((r, c))
        hidden_cols = {k for k, d in ws.column_dimensions.items() if d.hidden}
        hidden_rows = 0
        lines = [f"=== sheet '{ws.title}' ==="]
        for row in ws.iter_rows():
            if not row:
                continue
            r = row[0].row
            if ws.row_dimensions[r].hidden:
                if any(c.value is not None for c in row):
                    hidden_rows += 1
                continue
            cells = []
            for c in row:
                if (r, c.column) in merged_cover:
                    continue
                if get_column_letter(c.column) in hidden_cols:
                    continue
                s = _cell_str(c.value)
                if not s:
                    cells.append("")
                    continue
                if c.font is not None and c.font.strike:
                    s = f"[STRUCK: {s}]"
                if (r, c.column) in merged_first:
                    s += f"   [merged cell {merged_first[(r, c.column)]}]"
                cells.append(s)
            while cells and cells[-1] == "":
                cells.pop()
            if any(cells):
                lines.append(f"[row {r}] " + " | ".join(cells))
        if hidden_rows:
            doc.notes.append(f"sheet '{ws.title}': {hidden_rows} hidden row(s) omitted")
        if hidden_cols:
            doc.notes.append(f"sheet '{ws.title}': hidden column(s) {sorted(hidden_cols)} omitted")
        out.append("\n".join(lines))
    doc.text = "\n\n".join(out)
    if not doc.text.strip():
        doc.error = "spreadsheet has no visible content"
        doc.kind = "unreadable"
    return _cap(doc)


# --------------------------------------------------------------------------- Word

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


def _w_on(el) -> bool:
    if el is None:
        return False
    v = el.get(W + "val")
    return v is None or v.lower() not in ("0", "false", "none")


def _para_text(p) -> str:
    parts = []
    for r in p.iter(W + "r"):
        rpr = r.find(W + "rPr")
        struck = rpr is not None and (_w_on(rpr.find(W + "strike")) or _w_on(rpr.find(W + "dstrike")))
        t = "".join((x.text or "") if x.tag == W + "t" else ("\t" if x.tag == W + "tab" else "")
                    for x in r if x.tag in (W + "t", W + "tab"))
        if not t:
            continue
        parts.append(f"[STRUCK: {t}]" if struck else t)
    s = "".join(parts)
    return re.sub(r"\]\[STRUCK: ", "", s)


def _strip_deletions(root):
    for parent in root.iter():
        for child in list(parent):
            if child.tag in (W + "del", W + "moveFrom"):
                parent.remove(child)


def read_docx(filename: str, data: bytes) -> Doc:
    try:
        z = zipfile.ZipFile(io.BytesIO(data))
        root = ET.fromstring(z.read("word/document.xml"))
    except Exception as e:
        return Doc(filename, "unreadable", error=f"Word document could not be opened (corrupt): {e}")
    _strip_deletions(root)
    body = root.find(W + "body")
    lines = []

    def walk(el):
        for child in el:
            if child.tag == W + "p":
                t = _para_text(child)
                if t.strip():
                    style = child.find(f"{W}pPr/{W}pStyle")
                    sv = style.get(W + "val") if style is not None else ""
                    lines.append((f"[{sv}] " if sv and sv.lower().startswith(("heading", "title")) else "") + t)
            elif child.tag == W + "tbl":
                lines.append("[table]")
                for tr in child.iter(W + "tr"):
                    cells = []
                    for tc in tr.findall(W + "tc"):
                        cells.append(" ".join(_para_text(p) for p in tc.iter(W + "p")).strip())
                    if any(cells):
                        lines.append(" | ".join(cells))
                lines.append("[/table]")
            elif child.tag == W + "sdt":
                c = child.find(W + "sdtContent")
                if c is not None:
                    walk(c)

    if body is not None:
        walk(body)
    doc = Doc(filename, "text", text="\n".join(lines))
    # images embedded in the document (e.g. a pasted photo of a list)
    for n in z.namelist():
        if n.startswith("word/media/") and len(doc.images) < MAX_IMAGE_PAGES:
            try:
                png, w, h = image_for_model(z.read(n))
                if max(w, h) >= 200:
                    doc.images.append((f"{filename} embedded {n.rsplit('/', 1)[-1]}", png))
            except Exception:
                pass
    if doc.images:
        doc.kind = "mixed"
        doc.notes.append(f"{len(doc.images)} embedded picture(s) included")
    if not doc.text.strip() and not doc.images:
        doc.kind, doc.error = "unreadable", "Word document has no readable content"
    return _cap(doc)


# --------------------------------------------------------------------------- dispatch


def read_attachment(filename: str, mime: str, data: bytes, depth: int = 0) -> Doc:
    """Never raises."""
    try:
        if not data:
            return Doc(filename, "unreadable", error="attachment is empty (0 bytes)")
        kind = sniff(data, filename, mime)
        if kind == "pdf":
            return read_pdf(filename, data)
        if kind == "image":
            return read_image(filename, data)
        if kind == "xlsx":
            return read_xlsx(filename, data)
        if kind == "docx":
            return read_docx(filename, data)
        if kind == "csv":
            txt = _decode_text(data)
            try:
                rows = list(csv.reader(io.StringIO(txt)))
                txt = "\n".join(" | ".join(c.strip() for c in r) for r in rows if any(c.strip() for c in r))
            except Exception:
                pass
            return _cap(Doc(filename, "text", text=txt))
        if kind == "txt":
            return _cap(Doc(filename, "text", text=_decode_text(data)))
        if kind == "html":
            from .mime import html_to_text
            return _cap(Doc(filename, "text", text=html_to_text(_decode_text(data))))
        if kind == "eml":
            return read_eml(filename, data, depth)
        if kind == "ole":
            return Doc(filename, "unreadable", error="legacy Office file (.xls/.doc/.msg) - not supported, open by hand")
        if kind.startswith("mismatch:"):
            return Doc(filename, "unreadable",
                       error=f"file is named .{kind.split(':')[1]} but its contents are not that format (corrupt or mislabelled)")
        if kind == "corrupt_zip":
            return Doc(filename, "unreadable", error="file is a damaged ZIP/Office container")
        return Doc(filename, "unreadable", error=f"unsupported attachment type ({mime})")
    except Exception as e:
        return Doc(filename, "unreadable", error=f"could not read attachment: {type(e).__name__}: {e}")


def read_eml(filename: str, data: bytes, depth: int) -> Doc:
    from .mime import load_nested

    e = load_nested(data, filename, filename)
    txt = f"{e.headers_text}\n\n{e.body}"
    doc = Doc(filename, "text", text=txt, notes=["attached email message"])
    if depth < 2:
        for a in e.attachments:
            doc.nested.append(read_attachment(a.filename, a.mime, a.data, depth + 1))
    return _cap(doc)

toolUseResult.content:
"""Attachment bytes -> Doc (text and/or page images) for the model.

Code decides here, not the model:
  * what a file really is (magic bytes beat the extension),
  * what a human would not see: hidden sheets/rows/columns are dropped (they hold stale
    revisions), struck-through text is marked [STRUCK: ...], tracked deletions are dropped,
  * what cannot be read at all (password, corrupt, unsupported) -> Doc.error, which the
    pipeline turns into needs_review instead of a crash,
  * how much of a huge document is read (page / character caps -> Doc.truncated).
"""

from __future__ import annotations

import csv
import io
import re
import zipfile
from dataclasses import dataclass, field
from datetime import date, datetime
from xml.etree import ElementTree as ET

MAX_PDF_PAGES = 40  # text pages read from one PDF
MAX_IMAGE_PAGES = 8  # scanned pages rendered and sent as images, per document
MAX_DOC_CHARS = 60_000  # text sent per document
MAX_IMAGE_SIDE = 2000  # px, longest side sent to the model
MIN_IMAGE_SIDE = 24  # px, smaller images are spacers / tracking pixels
PAGE_TEXT_MIN = 25  # a PDF page with fewer characters is treated as a scan


@dataclass
class Doc:
    filename: str
    kind: str  # text | image | mixed | unreadable | skipped
    text: str = ""
    images: list[tuple[str, bytes]] = field(default_factory=list)  # (label, png/jpeg bytes)
    notes: list[str] = field(default_factory=list)
    error: str | None = None
    truncated: bool = False
    nested: list["Doc"] = field(default_factory=list)  # docs inside an attached .eml


def sniff(data: bytes, filename: str, mime: str) -> str:
    head = data[:8]
    if data[:5] == b"%PDF-" or b"%PDF-" in data[:1024]:
        return "pdf"
    if head.startswith(b"\x89PNG") or head.startswith(b"\xff\xd8") or head.startswith(b"GIF8") \
            or head.startswith(b"BM") or head[:4] in (b"II*\x00", b"MM\x00*") \
            or (data[:4] == b"RIFF" and data[8:12] == b"WEBP"):
        return "image"
    if head.startswith(b"PK"):
        try:
            names = zipfile.ZipFile(io.BytesIO(data)).namelist()
        except Exception:
            return "corrupt_zip"
        if any(n.startswith("xl/") for n in names):
            return "xlsx"
        if any(n.startswith("word/") for n in names):
            return "docx"
        return "zip"
    if head.startswith(b"\xd0\xcf\x11\xe0"):
        return "ole"  # legacy .xls/.doc/.msg
    ext = filename.lower().rsplit(".", 1)[-1] if "." in filename else ""
    if mime == "message/rfc822" or ext == "eml":
        return "eml"
    if ext in ("csv", "tsv") or mime in ("text/csv",):
        return "csv"
    if ext in ("htm", "html") or mime == "text/html":
        return "html"
    if ext in ("txt", "text") or mime.startswith("text/"):
        return "txt"
    if ext in ("pdf", "xlsx", "xlsm", "docx", "png", "jpg", "jpeg", "gif", "tif", "tiff", "bmp", "webp"):
        return "mismatch:" + ext  # name says one thing, bytes say another -> broken
    return "unknown"


def _decode_text(data: bytes) -> str:
    for enc in ("utf-8-sig", "cp1252", "latin-1"):
        try:
            return data.decode(enc)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", "replace")


def _cap(doc: Doc) -> Doc:
    if len(doc.text) > MAX_DOC_CHARS:
        doc.text = doc.text[:MAX_DOC_CHARS] + "\n[... TRUNCATED: document too long, rest not read ...]"
        doc.truncated = True
        doc.notes.append(f"text truncated at {MAX_DOC_CHARS} characters")
    return doc


# --------------------------------------------------------------------------- images


def image_for_model(data: bytes) -> tuple[bytes, int, int]:
    """Return (png bytes, width, height), downscaled to MAX_IMAGE_SIDE.  Raises if unreadable."""
    import fitz  # PyMuPDF

    pix = fitz.Pixmap(data)
    if pix.alpha:
        pix = fitz.Pixmap(pix, 0)
    if pix.colorspace and pix.colorspace.n not in (1, 3):
        pix = fitz.Pixmap(fitz.csRGB, pix)
    w, h = pix.width, pix.height
    side = max(w, h)
    if side > MAX_IMAGE_SIDE:
        scale = MAX_IMAGE_SIDE / side
        pix = fitz.Pixmap(pix, int(w * scale), int(h * scale), None)
    return pix.tobytes("png"), w, h


def read_image(filename: str, data: bytes) -> Doc:
    png, w, h = image_for_model(data)
    if max(w, h) < MIN_IMAGE_SIDE:
        return Doc(filename, "skipped", notes=[f"{w}x{h}px image ignored (spacer/tracking pixel)"])
    note = f"image {w}x{h}px"
    if h <= 100 and w <= 700:
        note += " (banner-sized: often a logo or signature graphic)"
    return Doc(filename, "image", images=[(filename, png)], notes=[note])


# --------------------------------------------------------------------------- PDF


def _pdf_lines(page) -> list[str]:
    """Rebuild visual lines from words so table rows stay on one line; wide gaps become ' | '.
    Text crossed by a horizontal rule through its middle is marked [STRUCK: ...]."""
    words = page.get_text("words")  # x0, y0, x1, y1, word, block, line, wno
    if not words:
        return []
    strikes = []
    try:
        for d in page.get_drawings():
            for it in d.get("items", []):
                if it[0] == "l":
                    p1, p2 = it[1], it[2]
                    if abs(p1.y - p2.y) < 1.5 and abs(p1.x - p2.x) > 8:
                        strikes.append((min(p1.x, p2.x), max(p1.x, p2.x), (p1.y + p2.y) / 2))
                elif it[0] == "re":
                    r = it[1]
                    if r.height < 2.0 and r.width > 8:
                        strikes.append((r.x0, r.x1, (r.y0 + r.y1) / 2))
    except Exception:
        strikes = []

    words = sorted(words, key=lambda w: ((w[1] + w[3]) / 2, w[0]))
    rows: list[list] = []
    for w in words:
        yc = (w[1] + w[3]) / 2
        if rows and abs(rows[-1][0] - yc) <= 3.0:
            rows[-1][1].append(w)
        else:
            rows.append([yc, [w]])
    out = []
    for _, ws in rows:
        ws.sort(key=lambda w: w[0])
        parts, prev = [], None
        for w in ws:
            if prev is not None:
                gap = w[0] - prev[2]
                parts.append(" | " if gap > 14 else " ")
            hgt = w[3] - w[1]
            struck = any(
                x0 <= w[0] + 1 and x1 >= w[2] - 1 and w[1] + 0.3 * hgt <= y <= w[3] - 0.3 * hgt
                for x0, x1, y in strikes
            )
            parts.append(f"[STRUCK: {w[4]}]" if struck else w[4])
            prev = w
        line = "".join(parts)
        line = re.sub(r"\]( |)\[STRUCK: ", " ", line)  # merge adjacent struck words
        out.append(line)
    return out


def read_pdf(filename: str, data: bytes) -> Doc:
    import fitz

    try:
        pdf = fitz.open(stream=data, filetype="pdf")
    except Exception as e:
        return Doc(filename, "unreadable", error=f"PDF could not be opened (corrupt or damaged): {e}")
    if pdf.needs_pass and not pdf.authenticate(""):
        return Doc(filename, "unreadable", error="PDF is password-protected; it cannot be opened without the password")
    doc = Doc(filename, "text")
    n = pdf.page_count
    if n == 0:
        return Doc(filename, "unreadable", error="PDF has no pages")
    texts, img_pages = [], 0
    for i in range(min(n, MAX_PDF_PAGES)):
        try:
            page = pdf[i]
            lines = _pdf_lines(page)
            txt = "\n".join(lines)
            if len(re.sub(r"\s", "", txt)) < PAGE_TEXT_MIN:
                if img_pages < MAX_IMAGE_PAGES:
                    pix = page.get_pixmap(dpi=150)
                    png, _, _ = image_for_model(pix.tobytes("png"))
                    doc.images.append((f"{filename} page {i + 1}", png))
                    img_pages += 1
                    texts.append(f"--- page {i + 1} of {n}: scanned image, see attached picture ---")
                else:
                    doc.truncated = True
                    texts.append(f"--- page {i + 1} of {n}: scanned image NOT READ (page limit) ---")
            else:
                texts.append(f"--- page {i + 1} of {n} ---\n{txt}")
        except Exception as e:
            texts.append(f"--- page {i + 1} of {n}: could not be read ({e}) ---")
            doc.notes.append(f"page {i + 1} unreadable: {e}")
            doc.truncated = True
    if n > MAX_PDF_PAGES:
        doc.truncated = True
        doc.notes.append(f"only the first {MAX_PDF_PAGES} of {n} pages were read")
        texts.append(f"[... {n - MAX_PDF_PAGES} more pages NOT READ (page limit) ...]")
    if img_pages >= MAX_IMAGE_PAGES and doc.truncated:
        doc.notes.append(f"only the first {MAX_IMAGE_PAGES} scanned pages were sent as images")
    doc.text = "\n".join(texts)
    doc.kind = "mixed" if doc.images and "\n" in doc.text else ("image" if doc.images else "text")
    return _cap(doc)


# --------------------------------------------------------------------------- Excel


def _cell_str(v) -> str:
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    if isinstance(v, (datetime, date)):
        return v.isoformat()[:10]
    return str(v).strip()


def read_xlsx(filename: str, data: bytes) -> Doc:
    import openpyxl
    from openpyxl.utils import get_column_letter

    try:
        wb = openpyxl.load_workbook(io.BytesIO(data), data_only=True)
    except Exception as e:
        return Doc(filename, "unreadable", error=f"spreadsheet could not be opened (corrupt or unsupported): {e}")
    doc = Doc(filename, "text")
    out = []
    for ws in wb.worksheets:
        if ws.sheet_state != "visible":
            n = sum(1 for r in ws.iter_rows(values_only=True) if any(c is not None for c in r))
            doc.notes.append(f"hidden sheet '{ws.title}' ({n} rows) omitted: hidden sheets hold old revisions/scratch work")
            continue
        merged_first = {}
        merged_cover = set()
        for rng in ws.merged_cells.ranges:
            merged_first[(rng.min_row, rng.min_col)] = rng.coord
            for r in range(rng.min_row, rng.max_row + 1):
                for c in range(rng.min_col, rng.max_col + 1):
                    if (r, c) != (rng.min_row, rng.min_col):
                        merged_cover.add((r, c))
        hidden_cols = {k for k, d in ws.column_dimensions.items() if d.hidden}
        hidden_rows = 0
        lines = [f"=== sheet '{ws.title}' ==="]
        for row in ws.iter_rows():
            if not row:
                continue
            r = row[0].row
            if ws.row_dimensions[r].hidden:
                if any(c.value is not None for c in row):
                    hidden_rows += 1
                continue
            cells = []
            for c in row:
                if (r, c.column) in merged_cover:
                    continue
                if get_column_letter(c.column) in hidden_cols:
                    continue
                s = _cell_str(c.value)
                if not s:
                    cells.append("")
                    continue
                if c.font is not None and c.font.strike:
                    s = f"[STRUCK: {s}]"
                if (r, c.column) in merged_first:
                    s += f"   [merged cell {merged_first[(r, c.column)]}]"
                cells.append(s)
            while cells and cells[-1] == "":
                cells.pop()
            if any(cells):
                lines.append(f"[row {r}] " + " | ".join(cells))
        if hidden_rows:
            doc.notes.append(f"sheet '{ws.title}': {hidden_rows} hidden row(s) omitted")
        if hidden_cols:
            doc.notes.append(f"sheet '{ws.title}': hidden column(s) {sorted(hidden_cols)} omitted")
        out.append("\n".join(lines))
    doc.text = "\n\n".join(out)
    if not doc.text.strip():
        doc.error = "spreadsheet has no visible content"
        doc.kind = "unreadable"
    return _cap(doc)


# --------------------------------------------------------------------------- Word

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"


def _w_on(el) -> bool:
    if el is None:
        return False
    v = el.get(W + "val")
    return v is None or v.lower() not in ("0", "false", "none")


def _para_text(p) -> str:
    parts = []
    for r in p.iter(W + "r"):
        rpr = r.find(W + "rPr")
        struck = rpr is not None and (_w_on(rpr.find(W + "strike")) or _w_on(rpr.find(W + "dstrike")))
        t = "".join((x.text or "") if x.tag == W + "t" else ("\t" if x.tag == W + "tab" else "")
                    for x in r if x.tag in (W + "t", W + "tab"))
        if not t:
            continue
        parts.append(f"[STRUCK: {t}]" if struck else t)
    s = "".join(parts)
    return re.sub(r"\]\[STRUCK: ", "", s)


def _strip_deletions(root):
    for parent in root.iter():
        for child in list(parent):
            if child.tag in (W + "del", W + "moveFrom"):
                parent.remove(child)


def read_docx(filename: str, data: bytes) -> Doc:
    try:
        z = zipfile.ZipFile(io.BytesIO(data))
        root = ET.fromstring(z.read("word/document.xml"))
    except Exception as e:
        return Doc(filename, "unreadable", error=f"Word document could not be opened (corrupt): {e}")
    _strip_deletions(root)
    body = root.find(W + "body")
    lines = []

    def walk(el):
        for child in el:
            if child.tag == W + "p":
                t = _para_text(child)
                if t.strip():
                    style = child.find(f"{W}pPr/{W}pStyle")
                    sv = style.get(W + "val") if style is not None else ""
                    lines.append((f"[{sv}] " if sv and sv.lower().startswith(("heading", "title")) else "") + t)
            elif child.tag == W + "tbl":
                lines.append("[table]")
                for tr in child.iter(W + "tr"):
                    cells = []
                    for tc in tr.findall(W + "tc"):
