        doc.kind = "mixed"
        doc.notes.append(f"{len(doc.images)} embedded picture(s) included")
    if not doc.text.strip() and not doc.images:
        doc.kind, doc.error = "unreadable", "Word document has no readable content"
    return _cap(doc)


# --------------------------------------------------------------------------- dispatch


def read_attachment(filename: str, mime: str, data: bytes, depth: int = 0) -> Doc:
    """Never raises."""
    try:
        if not data:
            return Doc(filename, "unreadable", error="attachment is empty (0 bytes)")
