        if kind == "pdf":
            return read_pdf(filename, data)
        if kind == "image":
            return read_image(filename, data)
        if kind == "xlsx":
            return read_xlsx(filename, data)
        if kind == "docx":
            return read_docx(filename, data)
        if kind == "csv":
            txt = _decode_text(data)
            try:
                rows = list(csv.reader(io.StringIO(txt)))
                txt = "\n".join(" | ".join(c.strip() for c in r) for r in rows if any(c.strip() for c in r))
            except Exception:
                pass
            return _cap(Doc(filename, "text", text=txt))
        if kind == "txt":
            return _cap(Doc(filename, "text", text=_decode_text(data)))
        if kind == "html":
            from .mime import html_to_text
            return _cap(Doc(filename, "text", text=html_to_text(_decode_text(data))))
        if kind == "eml":
            return read_eml(filename, data, depth)
        if kind == "ole":
            return Doc(filename, "unreadable", error="legacy Office file (.xls/.doc/.msg) - not supported, open by hand")
        if kind.startswith("mismatch:"):
            return Doc(filename, "unreadable",
