"""OpenAI Chat Completions over plain HTTPS (stdlib only), with a replay cache, retries,
a circuit breaker and cost accounting.

Cache key = hash(prompt version, model, extractor version, the email's own bytes, the bytes of
any thread-context emails).  It deliberately does NOT hash the rendered request: a different
PyMuPDF/openpyxl on the grader's machine may render a page slightly differently, and the dev
run must still replay with no API key.
"""

from __future__ import annotations

import base64
import hashlib
import json
import os
import random
import threading
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path

API_URL = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/") + "/chat/completions"
DEFAULT_MODEL = "gpt-4.1"

# USD per 1M tokens: (input, cached input, output).  Override with RFQ_PRICE="in,cached,out".
PRICES = {
    "gpt-4.1": (2.00, 0.50, 8.00),
    "gpt-4.1-mini": (0.40, 0.10, 1.60),
    "gpt-4.1-nano": (0.10, 0.025, 0.40),
    "gpt-4o": (2.50, 1.25, 10.00),
    "gpt-4o-mini": (0.15, 0.075, 0.60),
    "gpt-5": (1.25, 0.125, 10.00),
    "gpt-5-mini": (0.25, 0.025, 2.00),
}


def model_name() -> str:
    return os.environ.get("RFQ_MODEL", DEFAULT_MODEL)


def price_for(model: str) -> tuple[float, float, float] | None:
    env = os.environ.get("RFQ_PRICE")
    if env:
        try:
            a, b, c = (float(x) for x in env.split(","))
            return a, b, c
        except ValueError:
            pass
    for k in sorted(PRICES, key=len, reverse=True):  # longest prefix wins (gpt-4.1-mini before gpt-4.1)
        if model == k or model.startswith(k + "-20"):
            return PRICES[k]
    return None


def cost_usd(model: str, usage: dict) -> float | None:
    p = price_for(model)
    if not p or not usage:
        return None
    pin = usage.get("prompt_tokens", 0)
    cached = (usage.get("prompt_tokens_details") or {}).get("cached_tokens", 0) or 0
    out = usage.get("completion_tokens", 0)
    return round(((pin - cached) * p[0] + cached * p[1] + out * p[2]) / 1e6, 6)


class ModelUnavailable(Exception):
    """No key, provider down, circuit open, or the response could not be used."""


@dataclass
class CallResult:
    data: dict
    usage: dict
    cost: float | None
    model: str
    cached: bool
    latency_s: float
    attempts: int = 1


@dataclass
class Breaker:
    """After `limit` consecutive provider failures, stop calling for the rest of the run:
    every remaining email degrades immediately instead of each waiting out its retries."""

    limit: int = 3
    failures: int = 0
    open_reason: str | None = None
    lock: threading.Lock = field(default_factory=threading.Lock)

    def check(self):
        if self.open_reason:
            raise ModelUnavailable(f"circuit open: {self.open_reason}")

    def ok(self):
        with self.lock:
            self.failures = 0

    def fail(self, reason: str, hard: bool = False):
        with self.lock:
            self.failures += 1
            if hard or self.failures >= self.limit:
                self.open_reason = reason


class Cache:
    def __init__(self, root: Path):
        self.root = root

    def path(self, key: str) -> Path:
        return self.root / f"{key}.json"

    def get(self, key: str) -> dict | None:
        p = self.path(key)
        if not p.exists():
            return None
        try:
            return json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            return None  # a corrupt cache entry is just a miss

    def put(self, key: str, entry: dict):
        self.root.mkdir(parents=True, exist_ok=True)
        tmp = self.path(key).with_suffix(".tmp")
        tmp.write_text(json.dumps(entry, indent=1, ensure_ascii=False), encoding="utf-8")
        os.replace(tmp, self.path(key))  # atomic: a crash never leaves half a file


def cache_key(parts: dict) -> str:
    return hashlib.sha256(json.dumps(parts, sort_keys=True).encode()).hexdigest()[:32]


def _content(text: str, images: list[tuple[str, bytes]]) -> list[dict] | str:
    if not images:
        return text
    parts: list[dict] = [{"type": "text", "text": text}]
    for label, data in images:
        mime = "image/jpeg" if data[:2] == b"\xff\xd8" else "image/png"
        parts.append({"type": "text", "text": f"[picture: {label}]"})
        parts.append({
            "type": "image_url",
            "image_url": {"url": f"data:{mime};base64,{base64.b64encode(data).decode()}", "detail": "high"},
        })
    return parts


class Client:
    def __init__(self, cache: Cache, breaker: Breaker | None = None, timeout: float = 180.0,
                 max_attempts: int = 4, offline: bool = False):
        self.cache = cache
        self.breaker = breaker or Breaker()
        self.timeout = timeout
        self.max_attempts = max_attempts
        self.offline = offline
        self.key = os.environ.get("OPENAI_API_KEY", "").strip()

    def complete(self, key: str, system: str, user_text: str, images: list[tuple[str, bytes]],
                 schema: dict, meta: dict) -> CallResult:
        hit = self.cache.get(key)
        if hit and "response" in hit:
            return CallResult(hit["response"], hit.get("usage", {}), hit.get("cost_usd"), hit.get("model", ""),
