    cached = (usage.get("prompt_tokens_details") or {}).get("cached_tokens", 0) or 0
    out = usage.get("completion_tokens", 0)
    return round(((pin - cached) * p[0] + cached * p[1] + out * p[2]) / 1e6, 6)


class ModelUnavailable(Exception):
    """No key, provider down, circuit open, or the response could not be used."""


@dataclass
class CallResult:
    data: dict
    usage: dict
    cost: float | None
    model: str
    cached: bool
    latency_s: float
    attempts: int = 1


@dataclass
class Breaker:
    """After `limit` consecutive provider failures, stop calling for the rest of the run:
    every remaining email degrades immediately instead of each waiting out its retries."""

    limit: int = 3
    failures: int = 0
    open_reason: str | None = None
    lock: threading.Lock = field(default_factory=threading.Lock)

    def check(self):
        if self.open_reason:
            raise ModelUnavailable(f"circuit open: {self.open_reason}")

    def ok(self):
        with self.lock:
            self.failures = 0

    def fail(self, reason: str, hard: bool = False):
        with self.lock:
            self.failures += 1
            if hard or self.failures >= self.limit:
                self.open_reason = reason


class Cache:
    def __init__(self, root: Path):
        self.root = root

    def path(self, key: str) -> Path:
        return self.root / f"{key}.json"

    def get(self, key: str) -> dict | None:
        p = self.path(key)
        if not p.exists():
            return None
        try:
            return json.loads(p.read_text(encoding="utf-8"))
        except Exception:
            return None  # a corrupt cache entry is just a miss

    def put(self, key: str, entry: dict):
        self.root.mkdir(parents=True, exist_ok=True)
        tmp = self.path(key).with_suffix(".tmp")
        tmp.write_text(json.dumps(entry, indent=1, ensure_ascii=False), encoding="utf-8")
        os.replace(tmp, self.path(key))  # atomic: a crash never leaves half a file


def cache_key(parts: dict) -> str:
    return hashlib.sha256(json.dumps(parts, sort_keys=True).encode()).hexdigest()[:32]


def _content(text: str, images: list[tuple[str, bytes]]) -> list[dict] | str:
    if not images:
        return text
    parts: list[dict] = [{"type": "text", "text": text}]
    for label, data in images:
        mime = "image/jpeg" if data[:2] == b"\xff\xd8" else "image/png"
        parts.append({"type": "text", "text": f"[picture: {label}]"})
        parts.append({
            "type": "image_url",
            "image_url": {"url": f"data:{mime};base64,{base64.b64encode(data).decode()}", "detail": "high"},
        })
    return parts


class Client:
    def __init__(self, cache: Cache, breaker: Breaker | None = None, timeout: float = 180.0,
                 max_attempts: int = 4, offline: bool = False):
        self.cache = cache
        self.breaker = breaker or Breaker()
        self.timeout = timeout
        self.max_attempts = max_attempts
        self.offline = offline
        self.key = os.environ.get("OPENAI_API_KEY", "").strip()

    def complete(self, key: str, system: str, user_text: str, images: list[tuple[str, bytes]],
                 schema: dict, meta: dict) -> CallResult:
        hit = self.cache.get(key)
        if hit and "response" in hit:
            return CallResult(hit["response"], hit.get("usage", {}), hit.get("cost_usd"), hit.get("model", ""),
                              cached=True, latency_s=0.0)
        if self.offline:
            raise ModelUnavailable("offline mode and no cached response")
        if not self.key:
            raise ModelUnavailable("OPENAI_API_KEY is not set and no cached response exists")
        self.breaker.check()

        model = model_name()
        body = {
            "model": model,
            "messages": [{"role": "system", "content": system},
                         {"role": "user", "content": _content(user_text, images)}],
            "response_format": {"type": "json_schema",
                                "json_schema": {"name": "rfq_email", "strict": True, "schema": schema}},
            "max_completion_tokens": 16000,
            "seed": 7,
        }
        if not model.startswith(("gpt-5", "o1", "o3", "o4")):
            body["temperature"] = 0
        payload = json.dumps(body).encode()

        last = "unknown error"
        t0 = time.monotonic()
        for attempt in range(1, self.max_attempts + 1):
            self.breaker.check()
            req = urllib.request.Request(API_URL, data=payload, method="POST", headers={
                "Authorization": f"Bearer {self.key}", "Content-Type": "application/json"})
            try:
                with urllib.request.urlopen(req, timeout=self.timeout) as r:
                    resp = json.loads(r.read().decode("utf-8"))
                choice = resp["choices"][0]
                msg = choice["message"]
                if msg.get("refusal"):
                    raise ModelUnavailable(f"model refused: {msg['refusal'][:200]}")
                if choice.get("finish_reason") == "length":
                    raise ModelUnavailable("model output hit the token limit (document too large for one call)")
                data = json.loads(msg["content"])
                usage = resp.get("usage", {})
                cost = cost_usd(model, usage)
                lat = round(time.monotonic() - t0, 2)
                self.breaker.ok()
                self.cache.put(key, {
                    "meta": meta, "model": resp.get("model", model), "requested_model": model,
                    "usage": usage, "cost_usd": cost, "latency_s": lat, "attempts": attempt,
                    "created": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
                    "request_text": user_text, "images": [lbl for lbl, _ in images],
                    "response": data,
                })
                return CallResult(data, usage, cost, model, cached=False, latency_s=lat, attempts=attempt)
            except urllib.error.HTTPError as e:
                detail = ""
                try:
                    detail = e.read().decode("utf-8", "replace")[:300]
                except Exception:
                    pass
                last = f"HTTP {e.code}: {detail}"
                if e.code in (401, 403):
                    self.breaker.fail(last, hard=True)  # bad key: no point trying the rest
                    raise ModelUnavailable(last)
                if e.code == 400:
                    raise ModelUnavailable(last)  # our request is wrong for this email; retrying won't help
                retry_after = e.headers.get("retry-after") if e.headers else None
                wait = float(retry_after) if retry_after and retry_after.replace(".", "").isdigit() else 2 ** attempt
            except ModelUnavailable:
                raise
            except (urllib.error.URLError, TimeoutError, ConnectionError, OSError) as e:
                last = f"network: {e}"
                wait = 2 ** attempt
            except (KeyError, ValueError, json.JSONDecodeError) as e:
                last = f"bad response: {e}"
                wait = 1
            if attempt < self.max_attempts:
                time.sleep(min(wait, 30) + random.random())
        self.breaker.fail(last)
        raise ModelUnavailable(f"gave up after {self.max_attempts} attempts: {last}")

