"""Decisions code makes BEFORE (and instead of) a model call.

Each rule is deliberately narrow: it fires only on signals a machine put there (RFC 3834
headers, mailer-daemon senders, bulk-mail headers) or on byte-identical resends.  When a rule
is unsure it returns None and the email goes to the model.  A wrong 'skip' here is a silent
loss, so precision beats coverage.
"""

from __future__ import annotations

import re
from datetime import timedelta

from .extract import Doc
from .mime import Email

_BOUNCE_SENDER = re.compile(r"^(mailer-daemon|postmaster|mail-daemon|bounces?)@", re.I)
_AUTO_SUBJECT = re.compile(
    r"^\s*(automatic reply|auto(matic)?[- ]?reply|autoreply|out of (the )?office|ooo\b|undeliverable|"
    r"undelivered mail|delivery status notification|delivery (has )?failed|mail delivery failed|"
    r"returned mail|read:|delivered:|failure notice)",
    re.I,
)


def norm_subject(s: str) -> str:
    s = s or ""
    while True:
        t = re.sub(r"^\s*(re|fw|fwd|aw|sv|resend|resent|re-send)\s*(\[\d+\])?\s*:\s*", "", s, flags=re.I)
        if t == s:
            break
        s = t
    return re.sub(r"\s+", " ", s).strip().lower()


def _header(e: Email, name: str) -> str:
    for h in e.auto_headers:
        k, _, v = h.partition(":")
        if k.strip().lower() == name:
            return v.strip().lower()
    return ""


def auto_reply(e: Email) -> str | None:
    if _header(e, "auto-submitted").startswith("auto-replied"):
        return "Auto-Submitted: auto-replied header"
    if _header(e, "x-autoreply") or _header(e, "x-autorespond"):
        return "X-Autoreply header"
    if _BOUNCE_SENDER.match(e.from_addr or ""):
        return f"sent by {e.from_addr}"
    if _AUTO_SUBJECT.match(e.subject or "") and not e.from_us:
        return f"subject '{e.subject[:60]}'"
    return None


def bulk_marketing(e: Email, raw_headers: dict) -> str | None:
    prec = _header(e, "precedence")
    has_unsub = bool(raw_headers.get("list-unsubscribe")) or re.search(r"\bunsubscribe\b", e.body, re.I)
    if prec in ("bulk", "list", "junk") and has_unsub and not e.in_reply_to and not e.from_us:
        return f"Precedence: {prec} + unsubscribe link"
    return None


def _digit_lines(text: str) -> set[str]:
    out = set()
    for ln in text.splitlines():
        n = re.sub(r"[^a-z0-9/#\"]+", " ", ln.lower()).strip()
        if re.search(r"\d", n):
            out.add(n)
    return out


def _payload_hashes(e: Email, docs: list[Doc]) -> set[str]:
    """Attachments that carry content (not logos / banners / spacers)."""
    hs = set()
    for a, d in zip(e.attachments, docs):
        if d.kind == "skipped":
            continue
        if d.kind == "image" and any("banner-sized" in n for n in d.notes):
            continue
        hs.add(a.sha256)
    return hs


def exact_resend(e: Email, docs: list[Doc], earlier: list[tuple[Email, list[Doc]]]) -> tuple[str, str] | None:
    """The same request sent again: same sender, within 30 days, the same attachment bytes, and
    no item-like line in the new body that the earlier body did not already have.  Returns
    (earlier email id, reason).  Anything less certain goes to the model and the post-parse
    duplicate check."""
    if e.date is None or e.in_reply_to:
        return None
    mine = _payload_hashes(e, docs)
    my_lines = _digit_lines(e.current)
    for o, odocs in sorted(earlier, key=lambda x: x[0].date, reverse=True):
        if o.from_addr.lower() != e.from_addr.lower() or o.date is None:
            continue
        if not (timedelta(0) < e.date - o.date <= timedelta(days=30)):
            continue
        theirs = _payload_hashes(o, odocs)
        if mine != theirs:
            continue
        if not mine and not my_lines:
            continue  # nothing to compare
        if my_lines - _digit_lines(o.current):
            continue  # the resend adds or changes something: let the model read it
        why = "identical attachment(s)" if mine else "identical item lines"
        return o.id, f"resend of {o.id}: same sender, {why}, nothing new in the body"
    return None

