"""inbox dir -> parsed.json + run report.

Stages (each email isolated in try/except; one bad email never stops the run):
  1 load + read attachments                    code
  2 rules: auto-reply / bulk / exact resend    code (no model call)
  3 thread context for replies                 code
  4 one structured call per remaining email    model (cached by input bytes)
  5 validate + enforce the contract            code
  6 duplicates (post-parse) and `revises`      code
"""

from __future__ import annotations

import json
import re
import sys
import time
import traceback
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field
from datetime import timedelta
from pathlib import Path

from . import prompt as P
from . import rules
from .extract import Doc, read_attachment
from .llm import Breaker, Cache, Client, ModelUnavailable, cache_key, model_name
from .mime import Email, load_email

EXTRACTOR_VERSION = "x2"
REQUEST_CLASSES = ("rfq", "rfq_revision", "purchase_order")
MAX_HISTORY_CHARS = 8000
MAX_CONTEXT_CHARS = 6000

UOM_SYNONYMS = {
    "EACH": "EA", "PC": "EA", "PCS": "EA", "PIECE": "EA", "PIECES": "EA", "JT": "EA", "JTS": "EA", "JOINT": "EA",
    "JOINTS": "EA", "LENGTH": "EA", "LENGTHS": "EA", "STICK": "EA", "STICKS": "EA", "UNIT": "EA", "UNITS": "EA",
    "FEET": "FT", "FOOT": "FT", "LF": "FT", "LFT": "FT", "'": "FT", "METER": "M", "METERS": "M", "METRE": "M",
    "INCH": "IN", "INCHES": "IN", "BOX": "BX", "BOXES": "BX", "PACK": "PK", "PKG": "PK", "PAIR": "PR", "PAIRS": "PR",
    "DOZEN": "DZ", "ROLL": "RL", "ROLLS": "RL", "LBS": "LB", "POUND": "LB", "POUNDS": "LB", "SETS": "SET",
    "GALLON": "GAL", "GALLONS": "GAL", "BAGS": "BAG", "CASE": "CS", "CASES": "CS",
}


@dataclass
class Item:
    email: Email | None
    docs: list[Doc] = field(default_factory=list)
    result: dict | None = None
    report: dict = field(default_factory=dict)
    context: list[Email] = field(default_factory=list)


# --------------------------------------------------------------------------- helpers


def tokens(s: str) -> list[str]:
    s = (s or "").lower().replace("″", '"').replace("”", '"').replace("“", '"').replace("′", "'")
    return re.findall(r"[a-z0-9]+(?:[/.\-][a-z0-9]+)*", s)


def flat_docs(docs: list[Doc]) -> list[Doc]:
    out = []
    for d in docs:
        out.append(d)
        out.extend(flat_docs(d.nested))
    return out


def empty_result(classification: str) -> dict:
    return {"classification": classification, "revises": None, "duplicate_of": None,
            "needs_review": False, "review_reason": None, "line_items": []}


# --------------------------------------------------------------------------- stage 3: context


def find_context(e: Email, all_items: dict[str, Item]) -> list[Email]:
    """Earlier inbox emails this one replies to: by Message-ID chain, else (for a reply) by
    normalised subject from the same sender domain within 60 days."""
    if not (e.in_reply_to or e.references or re.match(r"^\s*(re|aw|sv)\s*:", e.subject or "", re.I)):
        return []
    ids = set(e.references) | ({e.in_reply_to} if e.in_reply_to else set())
    subj = rules.norm_subject(e.subject)
    found = []
    for it in all_items.values():
        o = it.email
        if o is None or o.id == e.id:
            continue
        if o.message_id and o.message_id in ids:
            found.append(o)
        elif (subj and rules.norm_subject(o.subject) == subj and o.sender_domain == e.sender_domain
              and o.date and e.date and timedelta(0) < e.date - o.date <= timedelta(days=60)):
            found.append(o)
    found.sort(key=lambda x: x.date.timestamp() if x.date else 0, reverse=True)
    return found[:2]


# --------------------------------------------------------------------------- stage 4: request


def _doc_block(i: int, d: Doc, cid_map: dict[str, str]) -> str:
    head = f"=== ATTACHMENT {i}: \"{d.filename}\""
    if d.filename in cid_map:
        head += f" (inline picture, shown in the body as {cid_map[d.filename]})"
    head += " ==="
    lines = [head]
    if d.notes:
        lines.append("(reader notes: " + "; ".join(d.notes) + ")")
    if d.error:
        lines.append(f"UNREADABLE: {d.error}")
    elif d.kind == "skipped":
        lines.append("(not sent: too small to contain content)")
    else:
        if d.text:
            lines.append(d.text)
        if d.images:
            lines.append(f"({len(d.images)} picture(s) of this attachment follow below)")
    return "\n".join(lines)


def build_request(e: Email, docs: list[Doc], context: list[tuple[Email, list[Doc]]]) -> tuple[str, list, list[str]]:
    sources = ["body"] + [d.filename for d in flat_docs(docs)]
    cid_map = {a.filename: f"cid:{a.content_id}" for a in e.attachments if a.content_id}
    who = ("ONE OF OUR OWN REPS (Ridgeline) - read the rep's note and the forwarded customer content"
           if e.from_us else "external sender")
    parts = [e.headers_text, f"Sender: {who}"]
    if e.auto_headers:
        parts.append("Mail headers: " + "; ".join(e.auto_headers))
    parts.append("\n=== CURRENT MESSAGE (what the sender wrote now) ===\n" + (e.current or "(empty)"))
    if e.history:
        label = ("FORWARDED MESSAGE (content being passed on to us)" if e.history_kind == "forward"
                 else "QUOTED EARLIER MESSAGES (history; context only)")
        h = e.history
        if len(h) > MAX_HISTORY_CHARS:
            h = h[:MAX_HISTORY_CHARS] + "\n[... older history cut ...]"
        parts.append(f"\n=== {label} ===\n{h}")
    images = []
    for i, d in enumerate(docs, 1):
        parts.append("\n" + _doc_block(i, d, cid_map))
        for n in d.nested:
            parts.append(_doc_block(i, n, {}).replace("=== ATTACHMENT", "=== ATTACHMENT INSIDE THE ATTACHED EMAIL", 1))
    for d in flat_docs(docs):
        if d.error or d.kind == "skipped":
            continue
        low = any("banner-sized" in n for n in d.notes)
        for label, data in d.images:
            images.append((label, data, "low" if low else "high"))
    for o, odocs in context:
        body = o.body if len(o.body) <= MAX_CONTEXT_CHARS else o.body[:MAX_CONTEXT_CHARS] + "\n[...]"
        block = [f"\n=== EARLIER EMAIL IN THIS THREAD, already in our inbox as {o.id} (context only) ===",
                 o.headers_text, body]
        for d in odocs:
            if d.text and not d.error:
                block.append(f"[its attachment {d.filename}]\n{d.text[:MAX_CONTEXT_CHARS]}")
        parts.append("\n".join(block))
    parts.append("\nValid `source` values: " + ", ".join(json.dumps(s) for s in sources))
    return "\n".join(parts), images, sources


# --------------------------------------------------------------------------- stage 5: validate


def _norm_uom(u) -> str | None:
    if u is None:
        return None
    s = str(u).strip().upper().rstrip(".")
    if s in P.UOMS:
        return s
    return UOM_SYNONYMS.get(s)


def _norm_qty(q):
    if q is None or isinstance(q, bool):
        return None
    if isinstance(q, (int, float)):
        if q <= 0:
            return None
        return int(q) if float(q).is_integer() else q
    try:
        f = float(str(q).replace(",", ""))
        return _norm_qty(f)
    except ValueError:
        return None


def _fix_source(src: str, sources: list[str], diags: list[str]) -> str:
    if src in sources:
        return src
    low = {s.lower(): s for s in sources}
    if (src or "").lower() in low:
        return low[src.lower()]
    for s in sources[1:]:
        if src and (src.lower() in s.lower() or s.lower() in src.lower()):
            return s
    files = sources[1:]
    fixed = files[0] if len(files) == 1 and src and src != "body" else "body"
    diags.append(f"source {src!r} not a real source; set to {fixed!r}")
    return fixed


def _squash(s: str) -> str:
    return re.sub(r"[^a-z0-9]", "", (s or "").lower().replace("″", '"'))


def validate(e: Email, docs: list[Doc], model_out: dict, sources: list[str]) -> tuple[dict, list[str]]:
    diags: list[str] = []
    cls = model_out.get("classification")
    if cls not in P.CLASSES:
        diags.append(f"invalid classification {cls!r} -> rfq + review")
        cls = "rfq"
        model_out["needs_review"] = True
        model_out["review_reason"] = "classifier returned an invalid class"
    out = empty_result(cls)
    if cls not in REQUEST_CLASSES:
        if model_out.get("line_items"):
            diags.append(f"{len(model_out['line_items'])} line(s) dropped: {cls} carries no lines")
        return out, diags

    texts = {"body": e.body}
    for d in flat_docs(docs):
        texts[d.filename] = d.text if not d.images else ""
    cur_sq, hist_sq = _squash(e.current), _squash(e.history)

    lines = []
    for ln in model_out.get("line_items") or []:
        raw = (ln.get("raw") or "").strip()
        desc = (ln.get("description") or "").strip() or raw
        if not raw and not desc:
            diags.append("empty line dropped")
            continue
        raw = raw or desc
        src = _fix_source(ln.get("source") or "body", sources, diags)
        # quoted reply history is not a request in a plain rfq (it was handled when it arrived)
        if (cls == "rfq" and src == "body" and e.history_kind == "reply_quote" and not e.from_us
                and len(_squash(raw)) >= 6 and _squash(raw) in hist_sq and _squash(raw) not in cur_sq):
            diags.append(f"dropped line from quoted history: {raw[:60]!r}")
            continue
        qty = _norm_qty(ln.get("qty"))
        uom = _norm_uom(ln.get("uom"))
        if ln.get("uom") and uom is None:
            diags.append(f"uom {ln.get('uom')!r} not allowed -> null")
        # grounding: every number the model put in `raw` should exist in that source's text
        st = texts.get(src, "")
        if st:
            src_nums = set(re.findall(r"\d+(?:[./-]\d+)*", st.replace("″", '"')))
            missing = [n for n in re.findall(r"\d+(?:[./-]\d+)*", raw) if n not in src_nums]
            if missing:
                diags.append(f"ungrounded numbers {missing} in raw {raw[:60]!r} (source {src})")
        lines.append({"raw": raw, "description": desc, "qty": qty, "uom": uom, "source": src})
    out["line_items"] = lines

    reasons = []
    if model_out.get("needs_review"):
        reasons.append((model_out.get("review_reason") or "model flagged for review").strip())
    for d in flat_docs(docs):
        if d.error:
            reasons.append(f"attachment {d.filename} could not be read: {d.error}")
        elif d.truncated:
            reasons.append(f"attachment {d.filename} only partly read: {'; '.join(d.notes) or 'size limit'}")
    if not lines:
        reasons.append("request with no line items that could be extracted")
    if reasons:
        out["needs_review"] = True
        seen, uniq = set(), []
        for r in reasons:
            if r.lower() not in seen:
                seen.add(r.lower())
                uniq.append(r)
        out["review_reason"] = "; ".join(uniq)[:500]
    return out, diags


# --------------------------------------------------------------------------- stage 6: threads


def _line_sig(ln: dict) -> tuple:
    return (ln.get("qty"), frozenset(tokens(ln.get("raw", ""))))


def _same_lines(a: list[dict], b: list[dict]) -> bool:
    if not a or not b or abs(len(a) - len(b)) > max(1, len(a) // 10):
        return False

    def covered(x, y):
        hit = 0
        for la in x:
            qa, ta = _line_sig(la)
            for lb in y:
                qb, tb = _line_sig(lb)
                if qa == qb and ta and len(ta & tb) / len(ta | tb) >= 0.8:
                    hit += 1
                    break
        return hit / len(x)

    return covered(a, b) >= 0.9 and covered(b, a) >= 0.9


def link_threads(items: dict[str, Item]):
    ordered = sorted((it for it in items.values() if it.email and it.result),
                     key=lambda it: (it.email.date.timestamp() if it.email.date else 0, it.email.id))
    # duplicates the rules could not prove up front: same customer, same lines, later date
    for i, it in enumerate(ordered):
        r = it.result
        if r["duplicate_of"] or r["classification"] not in ("rfq", "purchase_order") or not r["line_items"]:
            continue
        cust = (it.report.get("customer") or it.email.from_addr).lower()
        for prev in reversed(ordered[:i]):
            pr = prev.result
            if pr["classification"] != r["classification"] or pr["duplicate_of"]:
                continue
            pc = (prev.report.get("customer") or prev.email.from_addr).lower()
            if pc != cust or not (prev.email.date and it.email.date) or \
                    it.email.date - prev.email.date > timedelta(days=30):
                continue
            if _same_lines(pr["line_items"], r["line_items"]):
                it.result = {**empty_result(pr["classification"]), "duplicate_of": prev.email.id}
                it.report.setdefault("diagnostics", []).append(f"duplicate of {prev.email.id}: same customer, same lines")
                it.report["decided_by"] = it.report.get("decided_by", "model") + "+dedupe"
                break
    # rule-detected resends inherit the original's classification
    for it in ordered:
        d = it.report.get("resend_of")
        if d and d in items and items[d].result:
            root = items[d].result.get("duplicate_of") or d
            it.result = {**empty_result(items[root].result["classification"] if root in items and items[root].result
                                        else items[d].result["classification"]), "duplicate_of": root}
    # revisions point at the request they change, when it is in the inbox
    for it in ordered:
        if it.result["classification"] != "rfq_revision":
            continue
        for c in it.context:
            cr = items[c.id].result if c.id in items else None
            if cr and cr["classification"] in REQUEST_CLASSES:
                it.result["revises"] = cr.get("duplicate_of") or c.id
                break


# --------------------------------------------------------------------------- run


def fallback(e: Email | None, reason: str) -> dict:
    """Model unavailable: never drop the email silently.  Machine mail was already handled by
    rules, so anything left is treated as a possible request for a human."""
    r = empty_result("rfq")
    r["needs_review"] = True
    r["review_reason"] = f"automatic reading unavailable ({reason[:200]}); open the email by hand"
    return r


def run(emails_dir: Path, out_path: Path, cache_dir: Path, workers: int = 6, offline: bool = False,
        log=print) -> dict:
    t0 = time.monotonic()
    paths = sorted(emails_dir.glob("*.eml"))
    items: dict[str, Item] = {}

    # 1. load + read attachments (code)
    for p in paths:
        it = Item(None, report={"id": p.stem, "calls": 0, "cached": False, "prompt_tokens": 0,
                                "completion_tokens": 0, "cost_usd": 0.0, "diagnostics": []})
        try:
            it.email = load_email(p)
            it.docs = [read_attachment(a.filename, a.mime, a.data) for a in it.email.attachments]
            it.report["diagnostics"] += it.email.problems
            for d in flat_docs(it.docs):
                if d.error:
                    it.report["diagnostics"].append(f"{d.filename}: {d.error}")
        except Exception as ex:
            it.result = fallback(None, f"email could not be parsed: {ex}")
            it.report["decided_by"] = "error"
            it.report["error"] = traceback.format_exc(limit=3)
        items[p.stem] = it

    # 2. rules (code, no model call)
    by_date = sorted((it for it in items.values() if it.email), key=lambda it: it.email.date.timestamp()
                     if it.email.date else 0)
    for idx, it in enumerate(by_date):
        e = it.email
        try:
            why = rules.auto_reply(e)
            if why:
                it.result, it.report["decided_by"] = empty_result("auto_reply"), f"rule: {why}"
                continue
            why = rules.bulk_marketing(e)
            if why:
                it.result, it.report["decided_by"] = empty_result("other"), f"rule: {why}"
                continue
            earlier = [(o.email, o.docs) for o in by_date[:idx] if o.email.date and e.date and o.email.date < e.date]
            hit = rules.exact_resend(e, it.docs, earlier)
            if hit:
                it.result = {**empty_result("rfq"), "duplicate_of": hit[0]}
                it.report["decided_by"] = f"rule: {hit[1]}"
                it.report["resend_of"] = hit[0]
        except Exception as ex:
            it.report["diagnostics"].append(f"rules failed: {ex}")

    # 3 + 4. model calls (parallel, cached)
    client = Client(Cache(cache_dir), Breaker(), offline=offline)
    todo = [it for it in items.values() if it.result is None and it.email]

    def work(it: Item):
        e = it.email
        try:
            it.context = find_context(e, items)
            ctx = [(c, items[c.id].docs) for c in it.context]
            text, images, sources = build_request(e, it.docs, ctx)
            model = model_name(vision=bool(images))
            key = cache_key({"prompt": P.PROMPT_VERSION, "extractor": EXTRACTOR_VERSION, "model": model,
                             "email": e.raw_sha256, "context": [c.raw_sha256 for c in it.context]})
            res = client.complete(key, P.SYSTEM, text, images, P.SCHEMA,
                                  meta={"email": e.id, "context": [c.id for c in it.context]}, model=model)
            it.report.update({
                "calls": 0 if res.cached else res.attempts, "cached": res.cached, "model": res.model,
                "prompt_tokens": res.usage.get("prompt_tokens", 0),
                "cached_prompt_tokens": (res.usage.get("prompt_tokens_details") or {}).get("cached_tokens", 0),
                "completion_tokens": res.usage.get("completion_tokens", 0),
                "cost_usd": res.cost or 0.0, "latency_s": res.latency_s, "images": len(images),
                "decided_by": "model (cache)" if res.cached else "model",
                "customer": res.data.get("customer_email"),
                "reasoning": res.data.get("classification_reasoning"),
            })
            result, diags = validate(e, it.docs, res.data, sources)
            it.report["diagnostics"] += diags
            it.result = result
        except ModelUnavailable as ex:
            it.result = fallback(e, str(ex))
            it.report.update({"decided_by": "fallback", "error": str(ex)})
        except Exception as ex:
            it.result = fallback(e, f"{type(ex).__name__}: {ex}")
            it.report.update({"decided_by": "fallback", "error": traceback.format_exc(limit=4)})

    with ThreadPoolExecutor(max_workers=max(1, workers)) as pool:
        list(pool.map(work, todo))

    # 6. threads (code)
    try:
        link_threads(items)
    except Exception as ex:
        log(f"warning: thread linking failed: {ex}", file=sys.stderr)

    parsed = {k: items[k].result or fallback(items[k].email, "no result") for k in sorted(items)}
    out_path.parent.mkdir(parents=True, exist_ok=True)
    tmp = out_path.with_suffix(".tmp")
    tmp.write_text(json.dumps(parsed, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    tmp.replace(out_path)

    per = [items[k].report for k in sorted(items)]
    fresh = [r for r in per if r.get("calls")]
    recorded = [r for r in per if r.get("decided_by", "").startswith("model")]
    summary = {
        "emails": len(per),
        "new_model_calls": sum(r.get("calls", 0) for r in per),
        "emails_answered_from_cache": sum(1 for r in per if r.get("cached")),
        "emails_decided_by_rules": sum(1 for r in per if r.get("decided_by", "").startswith("rule")),
        "emails_degraded": sum(1 for r in per if r.get("decided_by") in ("fallback", "error")),
        "cost_usd_this_run": round(sum(r.get("cost_usd", 0) for r in fresh), 4),
        "recorded_cost_usd_all_model_emails": round(sum(r.get("cost_usd", 0) for r in recorded), 4),
        "recorded_tokens": {"prompt": sum(r.get("prompt_tokens", 0) for r in recorded),
                            "completion": sum(r.get("completion_tokens", 0) for r in recorded)},
        "seconds": round(time.monotonic() - t0, 1),
    }
    report = {"summary": summary, "emails": per}
    rp = out_path.with_name(out_path.stem + ".report.json")
    rp.write_text(json.dumps(report, indent=2, ensure_ascii=False, default=str) + "\n", encoding="utf-8")
    return report

