"""Score parsed.json against an answer key, the way data/README.md says we are graded.

Headline (worst first): silent losses, hallucinated lines, lost / phantom requests.
Then: classification accuracy, line recall / precision, and on paired lines qty, uom, source and
context carried (must_mention / must_not_mention), plus links and needs_review P/R.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

REQ = ("rfq", "rfq_revision", "purchase_order")
NON_REQ_PHANTOM = ("vendor_quote", "auto_reply", "other")

_EQUIV = [
    (r"schedule", "sch"),
    (r"class\s*(\d+)", r"\1#"),
    (r"(\d+)\s*(?:lbs?|pound)\b", r"\1#"),
    (r"butt\s*-?\s*weld(?:ed|ing)?", "bw"),
    (r"\bthreaded\b|\bnpt\b|\bthrd\b|\bthd\b", "thd"),
    (r"seamless", "smls"),
    (r"galvani[sz]ed|\bgalv\b", "galv"),
    (r"spiral[\s-]*wound", "spw"),
    (r"malleable(?:\s+iron)?", "mi"),
    (r"carbon\s+steel", "cs"),
    (r"full\s+port", "fp"),
    (r"elbows?|\bells?\b", "ell"),
    (r"valves?|\bvlv\b", "vlv"),
    (r"flanges?|\bflg\b", "flg"),
    (r"gaskets?|\bgskt\b", "gskt"),
    (r"reducers?", "red"),
    (r"couplings?|\bcplg\b", "cplg"),
]


def canon(s: str) -> str:
    s = (s or "").lower().replace("″", '"').replace("”", '"').replace("°", " ")
    for rx, rep in _EQUIV:
        s = re.sub(rx, rep, s)
    return re.sub(r"[^a-z0-9#]", "", s)


def mentions(desc: str, phrase: str) -> bool:
    d = canon(desc)
    return any(canon(alt) in d for alt in phrase.split("|"))


def toks(s: str) -> set[str]:
    s = (s or "").lower().replace("″", '"')
    return set(re.findall(r"[a-z0-9]+(?:[/.\-][a-z0-9]+)*", s))


def pair(pred: list[dict], key: list[dict]) -> list[tuple[int, int]]:
    cands = []
    for i, p in enumerate(pred):
        tp = toks(p.get("raw", "")) | toks(p.get("description", "")) * 0  # raw only, like the grader
        for j, k in enumerate(key):
            tk = toks(k["raw"])
            if not tp or not tk:
                continue
            sim = len(tp & tk) / len(tp | tk)
            if p.get("qty") == k.get("qty"):
                sim += 0.1
            if sim >= 0.3:
                cands.append((sim, i, j))
    cands.sort(reverse=True)
    used_p, used_k, out = set(), set(), []
    for _, i, j in cands:
        if i not in used_p and j not in used_k:
            used_p.add(i)
            used_k.add(j)
            out.append((i, j))
    return out


def qty_ok(pq, kq, tol) -> bool | None:
    if tol is None:
        return None
    if kq is None:
        return pq is None
    if pq is None:
        return False
    return abs(pq - kq) <= tol * abs(kq) + 1e-9


def main(parsed_path: Path, key_path: Path, verbose: bool = False) -> int:
    pred_all = json.loads(Path(parsed_path).read_text(encoding="utf-8"))
    key_all = json.loads(Path(key_path).read_text(encoding="utf-8"))["emails"]
    m = dict(emails=0, cls_ok=0, silent=0, halluc=0, lost=0, phantom=0, key_lines=0, pred_lines=0, paired=0,
             qty_n=0, qty_ok=0, uom_ok=0, src_ok=0, ctx_n=0, ctx_ok=0, link_n=0, link_ok=0,
             nr_tp=0, nr_fp=0, nr_fn=0)
    problems = []
    for eid, k in sorted(key_all.items()):
        p = pred_all.get(eid)
        m["emails"] += 1
        if p is None:
            problems.append(f"{eid}: MISSING from parsed.json")
            p = {"classification": None, "line_items": [], "needs_review": False}
        kc, pc = k["classification"], p.get("classification")
        if kc == pc:
            m["cls_ok"] += 1
        else:
            problems.append(f"{eid}: class {pc} (key {kc})")
        needs_action = bool(k["line_items"]) or k.get("needs_review")
        if needs_action and not p.get("line_items") and not p.get("needs_review"):
            m["silent"] += 1
            problems.append(f"{eid}: SILENT LOSS")
        if kc in REQ and pc not in REQ:
            m["lost"] += 1
        if kc in NON_REQ_PHANTOM and pc in REQ:
            m["phantom"] += 1
        for f in ("revises", "duplicate_of"):
            if k.get(f) or p.get(f):
                m["link_n"] += 1
                if k.get(f) == p.get(f):
                    m["link_ok"] += 1
                else:
                    problems.append(f"{eid}: {f} {p.get(f)} (key {k.get(f)})")
        kn, pn = bool(k.get("needs_review")), bool(p.get("needs_review"))
        m["nr_tp"] += kn and pn
        m["nr_fp"] += pn and not kn
        m["nr_fn"] += kn and not pn
        if pn != kn:
            problems.append(f"{eid}: needs_review {pn} (key {kn}) {p.get('review_reason') or ''}"[:200])

        pl, kl = p.get("line_items") or [], k["line_items"]
        m["key_lines"] += len(kl)
        m["pred_lines"] += len(pl)
        prs = pair(pl, kl)
        m["paired"] += len(prs)
        unp = set(range(len(pl))) - {i for i, _ in prs}
        unk = set(range(len(kl))) - {j for _, j in prs}
        m["halluc"] += len(unp)
        for i in sorted(unp):
            problems.append(f"{eid}: EXTRA line {pl[i].get('raw')!r}")
        for j in sorted(unk):
            problems.append(f"{eid}: MISSED line {kl[j]['raw']!r}")
        for i, j in prs:
            a, b = pl[i], kl[j]
            q = qty_ok(a.get("qty"), b.get("qty"), b.get("qty_tol"))
            if q is not None:
                m["qty_n"] += 1
                m["qty_ok"] += q
                if not q:
                    problems.append(f"{eid}: qty {a.get('qty')} (key {b.get('qty')}) on {b['raw']!r}")
            if (a.get("uom") or "EA") == (b.get("uom") or "EA"):
                m["uom_ok"] += 1
            else:
                problems.append(f"{eid}: uom {a.get('uom')} (key {b.get('uom')}) on {b['raw']!r}")
            if a.get("source") == b.get("source"):
                m["src_ok"] += 1
            else:
                problems.append(f"{eid}: source {a.get('source')!r} (key {b.get('source')!r})")
            if b.get("must_mention") or b.get("must_not_mention"):
                m["ctx_n"] += 1
                miss = [x for x in b.get("must_mention", []) if not mentions(a.get("description", ""), x)]
                bad = [x for x in b.get("must_not_mention", []) if mentions(a.get("description", ""), x)]
                if not miss and not bad:
                    m["ctx_ok"] += 1
                else:
                    problems.append(f"{eid}: context {b['raw']!r}: missing {miss} forbidden {bad} in "
                                    f"{a.get('description')!r}")

    def pct(a, b):
        return f"{100 * a / b:5.1f}% ({a}/{b})" if b else "  n/a"

    print("HEADLINE")
    print(f"  silent losses        {m['silent']}")
    print(f"  hallucinated lines   {m['halluc']}")
    print(f"  lost requests        {m['lost']}    phantom requests {m['phantom']}")
    print("DETAIL")
    print(f"  classification       {pct(m['cls_ok'], m['emails'])}")
    print(f"  line recall          {pct(m['paired'], m['key_lines'])}")
    print(f"  line precision       {pct(m['paired'], m['pred_lines'])}")
    print(f"  qty                  {pct(m['qty_ok'], m['qty_n'])}")
    print(f"  uom                  {pct(m['uom_ok'], m['paired'])}")
    print(f"  source               {pct(m['src_ok'], m['paired'])}")
    print(f"  context carried      {pct(m['ctx_ok'], m['ctx_n'])}")
    print(f"  links                {pct(m['link_ok'], m['link_n'])}")
    print(f"  needs_review         precision {pct(m['nr_tp'], m['nr_tp'] + m['nr_fp'])}  "
          f"recall {pct(m['nr_tp'], m['nr_tp'] + m['nr_fn'])}")
    if problems:
        print(f"\n{len(problems)} problem(s):" if verbose else f"\n{len(problems)} problem(s) (-v to list)")
        if verbose:
            for x in problems:
                print("  " + x)
    return 0

