"""MCP server (stdio, JSON-RPC 2.0, no SDK dependency) over the same pipeline and cache.

    python -m rfq.mcp_server

MCP is an interface here, not the engine: `parse` is the graded, deterministic path; this lets
a rep or an agent (Claude Desktop / Claude Code / any MCP client) ask "what is in E009?",
"why was E022 flagged?", "what did the code read out of that spreadsheet?".  It reads
OPENAI_API_KEY from its own environment and only uses it when an answer is not cached.

Register with Claude Code:
    claude mcp add rfq-inbox -- <path-to-python> -m rfq.mcp_server
"""

from __future__ import annotations

import json
import sys
import traceback
from pathlib import Path

from .cli import DEFAULT_CACHE, ROOT

PROTOCOL = "2025-06-18"
STATE: dict = {"dir": ROOT / "data" / "dev" / "emails", "parsed": None, "report": None}

TOOLS = [
    {
        "name": "parse_inbox",
        "description": "Parse every .eml in a directory (cached: re-runs cost nothing). Returns the run summary "
                       "(model calls, tokens, dollars, emails decided by rules / degraded).",
        "inputSchema": {"type": "object", "properties": {
            "emails_dir": {"type": "string", "description": "directory of .eml files (default: dev inbox)"},
            "offline": {"type": "boolean", "description": "never call the model"}}},
    },
    {
        "name": "list_emails",
        "description": "One row per email in the last parsed inbox: classification, line count, review flag, "
                       "links, and what decided it (rule / model / cache / fallback).",
        "inputSchema": {"type": "object", "properties": {}},
    },
    {
        "name": "get_email",
        "description": "Everything about one email: headers, the current message, the parsed result (lines with "
                       "sources), the model's reasoning, review reason, diagnostics and cost.",
        "inputSchema": {"type": "object", "required": ["email_id"],
                        "properties": {"email_id": {"type": "string", "description": "e.g. E009"}}},
    },
    {
        "name": "read_attachment",
        "description": "What the code read out of one attachment (text, notes such as hidden sheets omitted, "
                       "errors such as password-protected) - exactly what the model was shown.",
        "inputSchema": {"type": "object", "required": ["email_id", "filename"],
                        "properties": {"email_id": {"type": "string"}, "filename": {"type": "string"}}},
    },
]


def _ensure_parsed():
    if STATE["parsed"] is None:
        _parse_inbox({})


def _parse_inbox(args: dict) -> dict:
    from .pipeline import run

