OpenAI budget, and so the system is not tied to one vendor.  Uses the official `anthropic`
SDK (pip install anthropic) - imported lazily so the default install does not need it.
Structured output via output_config.format (json_schema); images as base64 image blocks.
"""

from __future__ import annotations

import base64
import json
import os

DEFAULT_MODEL = "claude-opus-5-5"

# USD per 1M tokens: (input, cache read, output).  Cache writes bill at 1.25x input.
PRICES = {
    "claude-opus-5-5": (4.00, 0.20, 20.00),
    "claude-sonnet-5-5": (2.00, 0.10, 10.00),
    "claude-haiku-5-5": (0.10, 0.01, 0.50),
}


class HardFailure(Exception):
    """Auth / permission: stop calling for the rest of the run."""


class SoftFailure(Exception):
    """Rate limit / overload / network after the SDK's own retries."""


class Unusable(Exception):
    """This email's request cannot succeed (bad request, refusal, truncated output)."""


def model_name() -> str:
    return os.environ.get("RFQ_ANTHROPIC_MODEL", DEFAULT_MODEL)


def cost_usd(model: str, u: dict) -> float | None:
    p = PRICES.get(model)
    if not p:
        return None
    return round((u.get("input_tokens", 0) * p[0] + u.get("cache_creation_input_tokens", 0) * p[0] * 1.25
                  + u.get("cache_read_input_tokens", 0) * p[1] + u.get("output_tokens", 0) * p[2]) / 1e6, 6)


def call(system: str, user_text: str, images: list[tuple[str, bytes, str]], schema: dict, model: str,
         timeout: float) -> tuple[dict, dict, str]:
