    try:
        import anthropic
    except ImportError as e:
        raise HardFailure("RFQ_PROVIDER=anthropic needs `pip install anthropic`") from e

    content: list[dict] = []
    for label, data, _detail in images:
        mime = "image/jpeg" if data[:2] == b"\xff\xd8" else "image/png"
        content.append({"type": "text", "text": f"[picture: {label}]"})
        content.append({"type": "image", "source": {"type": "base64", "media_type": mime,
                                                    "data": base64.standard_b64encode(data).decode()}})
    content.append({"type": "text", "text": user_text})

    client = anthropic.Anthropic(timeout=timeout, max_retries=3)
    try:
        with client.messages.stream(
            model=model,
            max_tokens=32000,
            system=[{"type": "text", "text": system, "cache_control": {"type": "ephemeral"}}],
            messages=[{"role": "user", "content": content}],
            output_config={"effort": os.environ.get("RFQ_ANTHROPIC_EFFORT", "medium"),
                           "format": {"type": "json_schema", "schema": schema}},
        ) as stream:
            msg = stream.get_final_message()
    except (anthropic.AuthenticationError, anthropic.PermissionDeniedError) as e:
        raise HardFailure(f"Anthropic auth failed: {e}") from e
    except anthropic.BadRequestError as e:
        raise Unusable(f"Anthropic rejected the request: {e}") from e
    except anthropic.RateLimitError as e:
        raise SoftFailure(f"Anthropic rate limit: {e}") from e
    except anthropic.APIStatusError as e:
        raise SoftFailure(f"Anthropic HTTP {e.status_code}: {e}") from e
    except anthropic.APIConnectionError as e:
        raise SoftFailure(f"Anthropic network error: {e}") from e

    if msg.stop_reason == "refusal":
        raise Unusable("model declined the request")
    if msg.stop_reason == "max_tokens":
        raise Unusable("model output hit the token limit (document too large for one call)")
    text = next((b.text for b in msg.content if b.type == "text"), None)
    if text is None:
        raise Unusable("no text block in response")
    data = json.loads(text)
    u = msg.usage
    raw = {"input_tokens": u.input_tokens or 0, "output_tokens": u.output_tokens or 0,
           "cache_read_input_tokens": getattr(u, "cache_read_input_tokens", 0) or 0,
           "cache_creation_input_tokens": getattr(u, "cache_creation_input_tokens", 0) or 0}
    usage = {"prompt_tokens": raw["input_tokens"] + raw["cache_read_input_tokens"] + raw["cache_creation_input_tokens"],
             "completion_tokens": raw["output_tokens"],
             "prompt_tokens_details": {"cached_tokens": raw["cache_read_input_tokens"]},
             "anthropic": raw, "request_id": getattr(msg, "_request_id", None)}
    return data, usage, msg.model

